var DATA = {"model": "F = k*x", "estimator": "Ordinary least squares", "data": "0,0|1,4.9|2,10.1|3,14.8|4,20.2"};
console.log("Model: " + DATA.model + " | Estimator: " + DATA.estimator);
// least squares fit y = a + b x
var pts = DATA.data.split("|").map(function (s) {
  var p = s.split(",").map(function (v) { return parseFloat(v); });
  return { x: p[0], y: p[1] };
});
var n = pts.length, sx = 0, sy = 0, sxx = 0, sxy = 0;
pts.forEach(function (p) { sx += p.x; sy += p.y; sxx += p.x * p.x; sxy += p.x * p.y; });
var b = (n * sxy - sx * sy) / (n * sxx - sx * sx), a = (sy - b * sx) / n;
var ssr = 0;
pts.forEach(function (p) { var r = p.y - (a + b * p.x); ssr += r * r; });
console.log("Fitted: y = " + a.toFixed(4) + " + " + b.toFixed(4) + " x  (n=" + n + ", SSR=" + ssr.toFixed(4) + ")");
console.log("RESULT: least-squares estimates a=" + a.toFixed(4) + ", b=" + b.toFixed(4) + ".");

